#!/usr/bin/env node
// Copies packages/fieldmap/src/fieldmap.{js,css} into apps/web/public with
// a content-hashed filename, and writes a manifest apps/web can import to
// find them. packages/fieldmap/src stays the only committed copy; the
// public/ files and the manifest are gitignored build output (see
// .gitignore) and regenerated by predev and prebuild (apps/web/package.json).
//
// Why a copy rather than the route handlers this replaced: a route handler
// built its path from process.cwd() assuming apps/web, but on Vercel a
// deployed function's cwd is the workspace root (outputFileTracingRoot in
// next.config.ts), which risked a 500 on first deploy. A plain static file
// in public/ has no such runtime path assumption.
//
// Why a content hash: so a browser that cached the previous deploy's
// /fieldmap.<hash>.js picks up a new one automatically (the href changes)
// instead of serving a stale script indefinitely.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, readdirSync, unlinkSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const webRoot = path.join(here, "..");
const srcDir = path.join(webRoot, "../../packages/fieldmap/src");
const publicDir = path.join(webRoot, "public");
const manifestPath = path.join(webRoot, "fieldmap-manifest.json");

function hashOf(contents) {
  return createHash("sha256").update(contents).digest("hex").slice(0, 10);
}

function copyHashed(name, ext) {
  const contents = readFileSync(path.join(srcDir, `${name}${ext}`));
  const hash = hashOf(contents);
  const outName = `${name}.${hash}${ext}`;
  writeFileSync(path.join(publicDir, outName), contents);
  return outName;
}

mkdirSync(publicDir, { recursive: true });

// Remove any previously copied hashed files so stale versions don't pile
// up in public/ across rebuilds.
for (const entry of readdirSync(publicDir)) {
  if (/^fieldmap\.[0-9a-f]{10}\.(js|css)$/.test(entry)) {
    unlinkSync(path.join(publicDir, entry));
  }
}

const manifest = {
  js: copyHashed("fieldmap", ".js"),
  css: copyHashed("fieldmap", ".css"),
};
writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n");

console.log("fieldmap assets copied:", manifest);
